HTML = HTML.replace("/*WORKFLOW_FRAGMENTS*/", ROOM_SCRIPT + "\n" + CONTROLLER_WORKFLOW_JS)

def management_html(*, trusted_lan_no_auth=False):
    if not trusted_lan_no_auth:
        return HTML
    return (HTML.replace(
        '<label id="authentication">Management token <input id="token" type="password" autocomplete="off"></label>',
        '<p id="trustedLanNotice">Trusted LAN access. Anyone who can reach this bridge on your LAN can control it.</p>')
        .replace('const authenticationRequired=true;', 'const authenticationRequired=false;')
        .replace('Enter your token to load the bridge.', 'Loading your bridge...')
        .replace('Connect / Refresh', 'Refresh'))
